function isDuplicate(username,email){const users=getUsers();const lu=username.toLowerCase(),le=email.toLowerCase();return users.some(u=>u.username.toLowerCase()===lu||u.email.toLowerCase()===le)}

const form=document.getElementById('regForm');
const fields={
username:{el:document.getElementById('username'),err:document.getElementById('usernameErr')},
email:{el:document.getElementById('email'),err:document.getElementById('emailErr')},
dob:{el:document.getElementById('dob'),err:document.getElementById('dobErr')},
password:{el:document.getElementById('password'),err:document.getElementById('pwErr')},
confirmPw:{el:document.getElementById('confirmPw'),err:document.getElementById('cpwErr')},
tos:{el:document.getElementById('tos'),err:document.getElementById('tosErr')}
};

function setError(key,msg){fields[key].err.textContent=msg;fields[key].el.classList.toggle('invalid',!!msg);if(msg)fields[key].el.setAttribute('aria-invalid','true');else fields[key].el.removeAttribute('aria-invalid')}
function clearErrors(){Object.keys(fields).forEach(k=>setError(k,''))}

function validate(){
let valid=true;clearErrors();
const u=fields.username.el.value.trim();
if(!u){setError('username','Username is required.');valid=false}
else if(u.length<3){setError('username','Username must be at least 3 characters.');valid=false}
else if(!/^[a-zA-Z0-9_]+$/.test(u)){setError('username','Only letters, numbers, and underscores allowed.');valid=false}

const e=fields.email.el.value.trim();
if(!e){setError('email','Email is required.');valid=false}
else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)){setError('email','Enter a valid email address.');valid=false}

const d=fields.dob.el.value;
if(d){const dt=new Date(d);const now=new Date();if(isNaN(dt)||dt>now){setError('dob','Date must be today or earlier.');valid=false}}

const p=fields.password.el.value;
if(!p){setError('password','Password is required.');valid=false}
else if(p.length<8){setError('password','Password must be at least 8 characters.');valid=false}

const cp=fields.confirmPw.el.value;
if(!cp){setError('confirmPw','Please confirm your password.');valid=false}
else if(cp!==p){setError('confirmPw','Passwords do not match.');valid=false}

if(!fields.tos.el.checked){setError('tos','You must accept the Terms of Service.');valid=false}

if(valid&&isDuplicate(u,e)){setError('username','This username is already registered.');setError('email','This email is already registered.');valid=false}

return valid;
}

form.addEventListener('submit',function(ev){
ev.preventDefault();
if(!validate())return;
saveUser({username:fields.username.el.value.trim(),email:fields.email.el.value.trim(),dob:fields.dob.el.value});
document.getElementById('successMsg').hidden=false;
form.reset();clearErrors();
fields.username.el.focus();
});

['username','email','dob','password','confirmPw'].forEach(k=>{
fields[k].el.addEventListener('blur',()=>validate());
fields[k].el.addEventListener('input',()=>{if(fields[k].err.textContent)validate()});
});
fields.tos.el.addEventListener('change',()=>validate());

document.querySelectorAll('.toggle-pw').forEach(btn=>{
btn.addEventListener('click',function(){
const inp=document.getElementById(this.dataset.target);
const showing=inp.type==='text';
inp.type=showing?'password':'text';
this.textContent=showing?'Show':'Hide';
this.setAttribute('aria-label',showing?'Show '+inp.labels[0].textContent:'Hide '+inp.labels[0].textContent);
inp.focus();
});
});
})();
</script>
